package nl.smartstreamlabs.sbwdroneconfig;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class DwfCreativeProductionTest {
 @Test void normalRecipeCannotSilentlyBecomeFree(){assertThrows(IllegalArgumentException.class,()->new DwfProduction.Recipe<String>("normal",Map.of(),"result",1,10));}
 @Test void creativeCraftPreservesRealStock(){var in=new DwfBulkStore<String>(100,10);var out=new DwfBulkStore<String>(100,10);in.insert("iron",31,false);var p=new DwfProduction<String>();p.select(new DwfProduction.Recipe<>("free",Map.of(),"result",2,10,true));p.start(1,false);assertFalse(p.visit(0,in,out,true));assertTrue(p.visit(10,in,out,true));assertEquals(2,out.count("result"));assertEquals(31,in.count("iron"));assertEquals(DwfProduction.State.IDLE,p.state());assertFalse(p.visit(20,in,out,true));}
 @Test void fullOutputDoesNotLoseOrOverflow(){var in=new DwfBulkStore<String>(100,10);var out=new DwfBulkStore<String>(2,10);out.insert("other",2,false);var p=new DwfProduction<String>();p.select(new DwfProduction.Recipe<>("free",Map.of(),"result",2,10,true));p.start(1,false);assertFalse(p.visit(0,in,out,true));assertEquals(DwfProduction.State.OUTPUT_FULL,p.state());assertFalse(p.visit(100,in,out,true));assertEquals(1,p.remaining());out.extract("other",2,false);assertFalse(p.visit(101,in,out,true));assertTrue(p.visit(111,in,out,true));assertEquals(2,out.total());}
 @Test void budgetAndUnloadNeverCauseCatchUpBurst(){var in=new DwfBulkStore<String>(100,10);var out=new DwfBulkStore<String>(100,10);var p=new DwfProduction<String>();p.select(new DwfProduction.Recipe<>("free",Map.of(),"result",1,5,true));p.start(1,true);p.visit(0,in,out,true);assertFalse(p.visit(10,in,out,false));assertTrue(p.visit(11,in,out,true));assertEquals(1,out.total());p.unload();assertFalse(p.visit(10000,in,out,true));assertEquals(1,out.total());assertTrue(p.visit(10005,in,out,true));assertEquals(2,out.total());}
 @Test void survivalStillConsumesAtomically(){var in=new DwfBulkStore<String>(100,10);var out=new DwfBulkStore<String>(100,10);var p=new DwfProduction<String>();p.select(new DwfProduction.Recipe<>("paid",Map.of("iron",3L),"result",1,5));p.start(1,false);p.visit(0,in,out,true);assertEquals(DwfProduction.State.MISSING_INPUT,p.state());in.insert("iron",3,false);p.visit(1,in,out,true);assertTrue(p.visit(6,in,out,true));assertEquals(0,in.total());assertEquals(1,out.total());}

 @Test void restoredCreativeBatchKeepsProgressAndRemainingWithoutOfflineCatchUp(){var in=new DwfBulkStore<String>(100,10);var out=new DwfBulkStore<String>(100,10);var recipe=new DwfProduction.Recipe<String>("free",Map.of(),"result",1,10,true);var p=new DwfProduction<String>();p.select(recipe);p.start(3,false);p.visit(0,in,out,true);p.visit(4,in,out,true);var saved=p.save();var loaded=new DwfProduction<String>();loaded.restore(saved,null);loaded.restore(loaded.save(),recipe);assertEquals(saved,loaded.save());assertFalse(loaded.visit(10000,in,out,true));assertEquals(4,loaded.progress());assertTrue(loaded.visit(10006,in,out,true));assertEquals(2,loaded.remaining());assertEquals(1,out.total());}
 @Test void restoredCreativeOffAndPausedOrdersStayStoppedUntilExplicitResume(){var in=new DwfBulkStore<String>(100,10);var out=new DwfBulkStore<String>(100,10);var recipe=new DwfProduction.Recipe<String>("free",Map.of(),"result",1,10,true);var p=new DwfProduction<String>();p.select(recipe);p.start(3,true);p.pause();var loaded=new DwfProduction<String>();loaded.restore(p.save(),recipe);assertFalse(loaded.visit(10000,in,out,true));assertEquals(DwfProduction.State.PAUSED,loaded.state());loaded.stop();var off=loaded.save();loaded.restore(off,recipe);assertFalse(loaded.visit(20000,in,out,true));assertEquals(0,out.total());assertFalse(loaded.save().enabled());}
}
